    local centre = r0 and r0.Position
    local t1 = os.clock()
    local hiding = false
    while RUNNING and A.alive() and os.clock() - t1 < 250 and M.attr("Zone") == "Dungeon" and not on("f_pause") do
        local hp = A.hp()
        if hp < 0.25 then
            LOG("dungeon leave low hp", math.floor(hp * 100))
            A.holdCF = nil
            M.call("Dungeon", "Leave")
            task.wait(2)
            break
        end
        local boss
        for _, t in ipairs(A.npcs()) do
            if bossName ~= "" and t.name:find(bossName, 1, true) then boss = t break end
        end
        if hiding or hp < 0.45 then
            if not hiding then hiding = true S.hides += 1 LOG("dungeon hide", math.floor(hp * 100)) end
            S.task = __T["Healing under the arena"]
            local c = (boss and boss.m.Parent and boss.m:GetPivot().Position) or centre
            if c then A.holdCF = CFrame.new(Vector3.new(c.X, (centre and centre.Y or c.Y) - 25, c.Z)) end
            if hp >= 0.8 then hiding = false A.holdCF = nil for p in pairs(A.ghosted) do pcall(function() p.CanCollide = true end) end A.ghosted = {} end
            task.wait(0.3)
        elseif boss then
            S.task = __T["Fighting "] .. bossName
            A.fight(boss, 4, 0.45)
            task.wait(0.05)
        else
            task.wait(0.2)
        end
    end
    A.holdCF = nil
    for p in pairs(A.ghosted) do pcall(function() p.CanCollide = true end) end
    A.ghosted = {}
