function A.farSpot()
    local n = M.attr("NestPosition")
    local origin = typeof(n) == "Vector3" and n or (M.root() and M.root().Position)
    if not origin then return nil end
    local avoid = {}
    for name in pairs(A.raiders) do
        local p = Players:FindFirstChild(name)
        local c = p and p.Character
        if c and c.PrimaryPart then avoid[#avoid + 1] = c.PrimaryPart.Position end
    end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    local ex = { lp.Character }
    if Workspace:FindFirstChild("Units") then ex[#ex + 1] = Workspace.Units end
    rp.FilterDescendantsInstances = ex
    local best, bestScore
    for i = 1, 16 do
        local ang = (i / 16) * math.pi * 2 + math.random() * 0.3
        local dist = val("a_moveDist", 350)
        local x, z = origin.X + math.cos(ang) * dist, origin.Z + math.sin(ang) * dist
        local hit = Workspace:Raycast(Vector3.new(x, origin.Y + 600, z), Vector3.new(0, -1200, 0), rp)
        if hit and hit.Material ~= Enum.Material.Water and hit.Instance and (hit.Instance:IsA("Terrain") or hit.Instance:IsDescendantOf(Workspace:FindFirstChild("Map") or Workspace)) then
            local score = 0
            for _, a in ipairs(avoid) do score = score + math.min((a - hit.Position).Magnitude, 800) end
            if #avoid == 0 then score = math.random() end
            if not bestScore or score > bestScore then best, bestScore = hit.Position, score end
        end
    end
    return best
end
